OOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.VIT, -2)\n    effect:addMod(xi.mod.CHR, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/cupid_chocolate.lua"]={["Path"]="scripts/items/cupid_chocolate.lua",["SHA256"]="f375e174ba8bc0fdd8c04b240cb9684fd226f0ec49cebe6cd1eb8d1abc486d58",["Text"]="-----------------------------------\n-- ID: 5681\n-- Item: cupid_chocolate\n-- Food Effect: 3Hrs, All Races\n-----------------------------------\n-- Accuracy +10\n-- Ranged Accuracy +10\n-- Attack 10\n-- Ranged Attack 10\n-- Store TP +25\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.ATT, 10)\n    effect:addMod(xi.mod.RATT, 10)\n    effect:addMod(xi.mod.ACC, 10)\n    effect:addMod(xi.mod.RACC, 10)\n    effect:addMod(xi.mod.STORETP, 25)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/curaga_earring.lua"]={["Path"]="scripts/items/curaga_earring.lua",["SHA256"]="c6f3516310acbc49755635bf3e90f80a31452da2315c8e53a4d8a8709186b315",["Text"]="-----------------------------------\n-- ID: 14759\n-- Item: Curaga Earring\n-- Item Effect: Casts weak \"Curaga\"\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\n-- Random roll for each target between 50 and 75\n-- Cure Pot, Cure Pot II, Cure Pot Received do not work\nitemObject.onItemUse = function(target, user, item, action)\n    local healAmount = math.randomInt(50, 75)\n\n    healAmount = healAmount * xi.settings.main.CURE_POWER\n\n    local diff = (target:getMaxHP() - target:getHP())\n    if healAmount > diff then\n        healAmount = diff\n    end\n\n    target:addHP(healAmount)\n    action:messageID(target:getID(), xi.msg.basic.RECOVERS_HP)\n\n    user:updateEnmityFromCure(target, healAmount) -- You do gain enmity from this\n\n    return healAmount\nend\n\nreturn itemObject\n"},["scripts/items/custom_gilet_+1.lua"]={["Path"]="scripts/items/custom_gilet_+1.lua",["SHA256"]="0bd4950461a83da390598b969c4c47bb071b7e32772d8782727ed54155cb7fa3",["Text"]="-----------------------------------\n-- ID: 11273\n-- Item: custom gilet +1\n-- Teleport's user to Purgonorgo Isle\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if not target:hasVisitedZone(xi.zone.BIBIKI_BAY) then\n        result = xi.msg.basic.ITEM_UNABLE_TO_USE_2\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.PURGONORGO, duration = 3, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/custom_top_+1.lua"]={["Path"]="scripts/items/custom_top_+1.lua",["SHA256"]="ba6cd28beb9443bf8f34ad8cf36c1396586e7bc07b2eb90f1892376fb4d885d1",["Text"]="-----------------------------------\n-- ID: 11274\n-- Item: custom top +1\n-- Teleport's user to Purgonorgo Isle\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if not target:hasVisitedZone(xi.zone.BIBIKI_BAY) then\n        result = xi.msg.basic.ITEM_UNABLE_TO_USE_2\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.PURGONORGO, duration = 3, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/cutlet_sandwich.lua"]={["Path"]="scripts/items/cutlet_sandwich.lua",["SHA256"]="4524ab32ab2ebe4eccba571648eb98186596fb61eb4cc36cb45b6a96c3f7ef07",["Text"]="-----------------------------------\n-- ID: 6396\n-- Item: cutlet_sandwich\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- HP +40\n-- STR +7\n-- INT -7\n-- Fire resistance +20\n-- Attack +20% (cap 120)\n-- Ranged Attack +20% (cap 120)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 40)\n    effect:addMod(xi.mod.STR, 7)\n    effect:addMod(xi.mod.INT, -7)\n    effect:addMod(xi.mod.FIRE_MEVA, 20)\n    effect:addMod(xi.mod.FOOD_ATTP, 20)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 120)\n    effect:addMod(xi.mod.FOOD_RATTP, 20)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 120)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/cutlet_sandwich_+1.lua"]={["Path"]="scripts/items/cutlet_sandwich_+1.lua",["SHA256"]="d940554d3d1263319ad56429183fac05d63033b142c744724b7cbaf82a2c0498",["Text"]="-----------------------------------\n-- ID: 6397\n-- Item: cutlet_sandwich_+1\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- HP +45\n-- STR +8\n-- INT -8\n-- Fire resistance +21\n-- Attack +21% (cap 125)\n-- Ranged Attack +21% (cap 125)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 45)\n    effect:addMod(xi.mod.STR, 8)\n    effect:addMod(xi.mod.INT, -8)\n    effect:addMod(xi.mod.FIRE_MEVA, 21)\n    effect:addMod(xi.mod.FOOD_ATTP, 21)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 125)\n    effect:addMod(xi.mod.FOOD_RATTP, 21)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 125)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/cyclical_coalescence.lua"]={["Path"]="scripts/items/cyclical_coalescence.lua",["SHA256"]="288ac757ab84a1dbe5a2ed62c58c8f655ac20c5b65badac60968c0f4d9a616ab",["Text"]="-----------------------------------\n-- ID: 6225\n-- Item: Cyclical coalescence\n-- Food Effect: 30 Min, All Races\n-----------------------------------\n-- MP +30% (cap 110)\n-- INT +7\n-- MND +7\n-- Magic Atk. Bonus +15\n-- Lizard Killer +7\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MPP, 30)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 110)\n    effect:addMod(xi.mod.INT, 7)\n    effect:addMod(xi.mod.MND, 7)\n    effect:addMod(xi.mod.MATT, 15)\n    effect:addMod(xi.mod.LIZARD_KILLER, 7)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/czars_belt.lua"]={["Path"]="scripts/items/czars_belt.lua",["SHA256"]="a2b55b5a63fc17bc5b8afc3018154c9a550212efb2f14155fa9939eea22051d8",["Text"]="-----------------------------------\n-- ID: 15868\n-- Item: czars_belt\n-- Item Effect: VIT +10\n-- Duration: 60 seconds\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.CZARS_BELT) ~= nil then\n        target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.CZARS_BELT)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.CZARS_BELT) then\n        target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 60, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.CZARS_BELT })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.VIT, 10)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/daedalus_wing.lua"]={["Path"]="scripts/items/daedalus_wing.lua",["SHA256"]="b166f3e23deeabe9bb5419f02c01598b3f71c151a5457c0cd8a88c8dc19e7dee",["Text"]="-----------------------------------\n-- ID: 4202\n-- Daedalus Wing\n-- Increases TP of the user by 1000\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:addTP(1000)\nend\n\nreturn itemObject\n"},["scripts/items/dagger_enchiridion.lua"]={["Path"]="scripts/items/dagger_enchiridion.lua",["SHA256"]="3a28ed6a0c9ecc92902710d78a525afb645b1ac654cee109d5e83f599ea9352e",["Text"]="-----------------------------------\n-- ID: 6148\n-- Item: Dagger enchiridion\n-- A guide to the finer points of wielding a dagger,\n-- written by an anonymous individual.\n-- Adventurers note that reading it increases one's dagger skill.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.skillBookCheck(target, xi.skill.DAGGER)\nend\n\nitemObject.onItemUse = function(target)\n    xi.itemUtils.skillBookUse(target, xi.skill.DAGGER)\nend\n\nreturn itemObject\n"},["scripts/items/dainslaif.lua"]={["Path"]="scripts/items/dainslaif.lua",["SHA256"]="bb7a972dc46e3e50736ccb1047b8aa4a12fdc0458f7aa43ecda7ac533163b4f6",["Text"]="-----------------------------------\n-- ID: 17651\n-- Item: Dainslaif\n-- Additional effect: en-drain\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n\n    local pTable =\n    {\n        chance          = xi.additionalEffect.linearProcRate(dStat, 40, 1, 20),\n        basePower       = 40 + utils.clamp(dStat, -3, 16) + utils.clamp(math.floor((dStat - 16) / 2), 0, 16),\n        attackType      = xi.attackType.PHYSICAL,\n        physicalElement = xi.damageType.SLASHING,\n        magicalElement  = xi.element.DARK,\n        canResist       = true,\n        lowestResist    = 0.5,\n        limitUndead     = true,\n        drainHP         = true,\n        overDrain       = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/damascus_bolt_quiver.lua"]={["Path"]="scripts/items/damascus_bolt_quiver.lua",["SHA256"]="e525bac3cb3ec18ffbc964b07f136b5beb97f94f30ca07c0c4128afdd273d9c5",["Text"]="-----------------------------------\n-- ID: 6140\n-- Item: Dm. Bolt Quiver\n-- When used, you will obtain one stack of Damascus Bolts\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.DAMASCUS_BOLT, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/damascus_bullet_pouch.lua"]={["Path"]="scripts/items/damascus_bullet_pouch.lua",["SHA256"]="25be2a9e224cc32f0a789eabde7cf25656e37b9653974bd3d18eb5d4893344a9",["Text"]="-----------------------------------\n-- ID: 6143\n-- Dm. Bul. Pouch\n-- When used, you will obtain one stack of Damascus Bullets\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.DAMASCUS_BULLET, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/dancer_die.lua"]={["Path"]="scripts/items/dancer_die.lua",["SHA256"]="bba3f0a79be757b56d4c65815b5e488ac45153ca4b472a9dae9d66104d4074c1",["Text"]="-----------------------------------\n-- ID: 5495\n-- Dancer Die\n-- Teaches the job ability Dancer's Roll\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnAbility(xi.jobAbility.DANCERS_ROLL)\nend\n\nitemObject.onItemUse = function(target)\n    target:addLearnedAbility(xi.jobAbility.DANCERS_ROLL)\nend\n\nreturn itemObject\n"},["scripts/items/danceshroom.lua"]={["Path"]="scripts/items/danceshroom.lua",["SHA256"]="4cfaa0a6b89cf3763268ff09ff6faf8d9f776a15371e6e29da306e32e1e9fd5d",["Text"]="-----------------------------------\n-- ID: 4375\n-- Item: danceshroom\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Strength -5\n-- Mind 3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, -5)\n    effect:addMod(xi.mod.MND, 3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/dark_adaman_bolt_quiver.lua"]={["Path"]="scripts/items/dark_adaman_bolt_quiver.lua",["SHA256"]="0e04b5e1a3c0f6edd51b0c692a75b119cd1da6515ac82a11683e30f97ac537d3",["Text"]="-----------------------------------\n-- ID: 5872\n-- Dark Adaman Bolt Quiver\n-- When used, you will obtain one stack of Dark Adaman Bolts\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.DARK_ADAMAN_BOLT, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/dark_adaman_bullet_pouch.lua"]={["Path"]="scripts/items/dark_adaman_bullet_pouch.lua",["SHA256"]="ba08686e38b3f067f03bc839d72e4a4d84fe240852004b1113e7f775d3edd2bb",["Text"]="-----------------------------------\n-- ID: 5873\n-- Dark Adaman Bullet Pouch\n-- When used, you will obtain one stack of Dark Adaman Bullets\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.DARK_ADAMAN_BULLET, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/dark_bass.lua"]={["Path"]="scripts/items/dark_bass.lua",["SHA256"]="2f75366d82adba985f064b5656058d1b0f30e27c517d2f48777336300f680ec2",["Text"]="-----------------------------------\n-- ID: 4428\n-- Item: dark_bass\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 2\n-- Mind -4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.MND, -4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/dark_card_case.lua"]={["Path"]="scripts/items/dark_card_case.lua",["SHA256"]="ea1ba063e1dd15e4df35b2bebcc2d4055cc808eed5fd0104ae996e5a3e80db59",["Text"]="-----------------------------------\n-- ID: 5409\n-- Dark Card Case\n-- When used, you will obtain one stack of Dark Cards\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.DARK_CARD, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/dark_cluster.lua"]={["Path"]="scripts/items/dark_cluster.lua",["SHA256"]="3478e1fe6419e671700e5a063f5f8bc8ff9ea1ffcaadda42ebe6181991ff8eb6",["Text"]="-----------------------------------\n-- ID: 4111\n-- Dark Cluster\n-- Turn into a stack of dark crystals\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.DARK_CRYSTAL, 12 } })\nend\n\nreturn itemObject\n"},["scripts/items/dark_knight_die.lua"]={["Path"]="scripts/items/dark_knight_die.lua",["SHA256"]="5f8e0bd979f1d11344000a4f6b90eece8e73ff7ddbd64f7dd7571883a85374ea",["Text"]="-----------------------------------\n-- ID: 5484\n-- Dark Knight Die\n-- Teaches the job ability Chaos Roll\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnAbility(xi.jobAbility.CHAOS_ROLL)\nend\n\nitemObject.onItemUse = function(target)\n    target:addLearnedAbility(xi.jobAbility.CHAOS_ROLL)\nend\n\nreturn itemObject\n"},["scripts/items/dark_spirit_pact.lua"]={["Path"]="scripts/items/dark_spirit_pact.lua",["SHA256"]="06182d45af62c2ecaf75a74568dcd9b5763f801e520402c2e0168f7f976254f6",["Text"]="-----------------------------------\n-- ID: 4903\n-- Dark Spirit Pact\n-- Teaches the summoning magic Dark Spirit\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnSpell(xi.magic.spell.DARK_SPIRIT)\nend\n\nitemObject.onItemUse = function(target)\n    target:addSpell(xi.magic.spell.DARK_SPIRIT)\nend\n\nreturn itemObject\n"},["scripts/items/dark_staff.lua"]={["Path"]="scripts/items/dark_staff.lua",["SHA256"]="5cea65dd3675e0ba3703cdb5cbc4d20006c6c3758d2f8c82276c53db575ea9eb",["Text"]="-----------------------------------\n-- ID: 17559\n-- Item: Dark Staff\n-- Additional effect: darkness damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 15, -- guessed\n        basePower      = math.randomInt(12, 16),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.DARK,\n        canMAB         = false,\n        canResist      = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/darkling_bolt.lua"]={["Path"]="scripts/items/darkling_bolt.lua",["SHA256"]="dbbae4d91767d2313592e0eb08f4f9aeadeea87d94ef35777b15fa6b944f6716",["Text"]="-----------------------------------\n-- ID: 19196\n-- Item: Darkling Bolt\n-- Additional effect: Darkness damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    -- Unconfirmed power.\n\n    local pTable =\n    {\n        ignoreEnSpell   = true,\n        basePower       = 10 + utils.clamp(dStat, -3, 8) + utils.clamp(math.floor((dStat - 8) / 2), 0, 8),\n        attackType      = xi.attackType.MAGICAL,\n        magicalElement  = xi.element.DARK,\n        canResist       = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/darkling_bolt_quiver.lua"]={["Path"]="scripts/items/darkling_bolt_quiver.lua",["SHA256"]="89bcb6ca63814d6509296f9919c29406fbf1c49dbd4a83921f28f79cf8ce28ec",["Text"]="-----------------------------------\n-- ID: 5820\n-- Darkling Bolt Quiver\n-- When used, you will obtain one stack of Darkling Bolts\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.DARKLING_BOLT, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/darksteel_bolt_quiver.lua"]={["Path"]="scripts/items/darksteel_bolt_quiver.lua",["SHA256"]="acb0b436cf47f0bf1e7fbea85b5026f2aa839c864b88fdd482b223cc649cac2a",["Text"]="-----------------------------------\n-- ID: 4229\n-- Darksteel Bolt Quiver\n-- When used, you will obtain one stack of Darksteel Bolts\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.DARKSTEEL_BOLT, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/date.lua"]={["Path"]="scripts/items/date.lua",["SHA256"]="cc9b154b384eb149ee1fe508486cc1b7107e18ed272b0c8828d5193a02bc5145",["Text"]="-----------------------------------\n-- ID: 5566\n-- Item: Date\n-- Food Effect: 5 Mins, All Races\n-----------------------------------\n-- Intelligence 1\n-- Agility -3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.INT, 1)\n    effect:addMod(xi.mod.AGI, -3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/date_shuriken_pouch.lua"]={["Path"]="scripts/items/date_shuriken_pouch.lua",["SHA256"]="7773757620f90c36cc97d80ae962a8014cf00d156817f4b2ecf9a61313c14531",["Text"]="-----------------------------------\n-- ID: 6449\n-- Date Suriken Pouch\n-- A small leather pouch made for storing Date Suriken.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.DATE_SHURIKEN, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/datechochin.lua"]={["Path"]="scripts/items/datechochin.lua",["SHA256"]="ecf23a799555aa1bb42be07c3f02ae100bf0735d6e923a8d26612c95f505c850",["Text"]="-----------------------------------\n-- ID: 5361\n-- Datechochin\n-- Turns the user into a floating yellow lantern\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\nend\n\nreturn itemObject\n"},["scripts/items/daybreak.lua"]={["Path"]="scripts/items/daybreak.lua",["SHA256"]="177fbb73095d94be2a58aa62e27a7ff0463cc3c8a5893b4f2ce431ce628b8ec8",["Text"]="-----------------------------------\n-- ID: 22040\n-- Daybreak\n-- Able to cast \"Dispelga\"\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\nend\n\nitemObject.onItemEquip = function(target, item)\n    local mainWeapon = target:getEquippedItem(xi.slot.MAIN)\n    if mainWeapon and mainWeapon:getID() == xi.item.DAYBREAK then\n        target:addSpell(xi.magic.spell.DISPELGA, { silentLog = true, saveToDB = false })\n    end\nend\n\nitemObject.onItemUnequip = function(target, item)\n    target:delSpell(xi.magic.spell.DISPELGA, { saveToDB = false })\nend\n\nreturn itemObject\n"},["scripts/items/deadeye_earring.lua"]={["Path"]="scripts/items/deadeye_earring.lua",["SHA256"]="16df50e66ccb78d35df5c753c193c6af8c7962f860833661e504cac7417245c8",["Text"]="-----------------------------------\n-- ID: 14787\n-- Item: Deadeye Earring\n-- Item Effect: Ranged Attack 20\n-- Duration: 3 Minutes\n-- https://wiki.ffo.jp/html/10067.html\n-- TODO: Capture Icon\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.DEADEYE_EARRING) then\n        local effect = target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.DEADEYE_EARRING)\n        if effect then\n            effect:resetStartTime()\n        else\n            target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 180, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.DEADEYE_EARRING })\n        end\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.RATT, 20)\nend\n\nitemObject.onItemUnequip = function(target, item)\n    target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.DEADEYE_EARRING)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/deae_gratia.lua"]={["Path"]="scripts/items/deae_gratia.lua",["SHA256"]="d773862ba591b94cd74e682f24234ed5069b2a91fe38d8b92f383d613257d8a0",["Text"]="-----------------------------------\n-- ID: 18856\n-- Item: Deae Gratia\n-- Additional effect: en-drain\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n\n    local pTable =\n    {\n        chance          = xi.additionalEffect.linearProcRate(dStat, 48, 15, 18),                              -- TODO: This actually caps above dINT 48 for proc rate\n        basePower       = 30 + utils.clamp(dStat, -3, 16) + utils.clamp(math.floor((dStat - 16) / 2), 0, 16), -- TODO: check the scaling formula\n        attackType      = xi.attackType.PHYSICAL,\n        physicalElement = xi.damageType.BLUNT,\n        magicalElement  = xi.element.DARK,\n        canResist       = true,\n        lowestResist    = 0.5,\n        limitUndead     = true,\n        drainHP         = true,\n        overDrain       = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/death_chakram.lua"]={["Path"]="scripts/items/death_chakram.lua",["SHA256"]="3aaeaadcad6b5268a53c7effe0a8911d458e36c82a0e3cc53823217bf94751d4",["Text"]="-----------------------------------\n-- ID: 18231\n-- Item: Death Chakram\n-- Item Effect: +5% MP\n-- Duration: 30 Minutes\n-- https://wiki.ffo.jp/html/4399.html\n-- TODO: Capture Icon\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.DEATH_CHAKRAM) then\n        local effect = target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.DEATH_CHAKRAM)\n        if effect then\n            effect:resetStartTime()\n        else\n            target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 1800, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.DEATH_CHAKRAM })\n        end\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.MPP, 5)\nend\n\nitemObject.onItemUnequip = function(target, item)\n    target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.DEATH_CHAKRAM)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/death_penalty.lua"]={["Path"]="scripts/items/death_penalty.lua",["SHA256"]="236bcab064ee3f22152b765cb1d496d1ed50e249dd3e8d74e133d1fe2621d4e7",["Text"]="-----------------------------------\n-- ID: 19007\n-- Item: Death Penalty\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getFreeSlotsCount() == 0 then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.LIVING_BULLET, 99 } }) -- Living Bullet x99\nend\n\nreturn itemObject\n"},["scripts/items/deathball.lua"]={["Path"]="scripts/items/deathball.lua",["SHA256"]="4481b5448f6e44c093f6cad5866d577a77b518516fbd768e251144f12186b0cd",["Text"]="-----------------------------------\n-- ID: 4566\n-- Item: Deathball\n-- Food Effect: 3 Mins, All Races\n-- Poison 2HP / 3Tic\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 180, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\n    if not target:hasStatusEffect(xi.effect.POISON) then\n        target:addStatusEffect(xi.effect.POISON, { power = 2, duration = 180, origin = user, tick = 3 })\n    else\n        target:messageBasic(xi.msg.basic.NO_EFFECT)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/deathbone_knife.lua"]={["Path"]="scripts/items/deathbone_knife.lua",["SHA256"]="7244a940ed89f5c6a403453bd00f8b9365ad232f3f97f888cd02d05f040b7191",["Text"]="-----------------------------------\n-- ID: 18035\n-- Item: Deathbone Knife\n-- Item Effect: TP +10\n-- Duration: Instant\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:addTP(100)\nend\n\nreturn itemObject\n"},["scripts/items/decennial_coat_+1.lua"]={["Path"]="scripts/items/decennial_coat_+1.lua",["SHA256"]="3ec331073ca9d381de434a5db1c310ff919907426653fa4efcb0e1041537534d",["Text"]="-----------------------------------\n-- ID: 10253\n-- Decennial Coat +1\n-- Dispense: Bowl of Moogurt\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.BOWL_OF_MOOGURT, 1 } })\nend\n\nreturn itemObject\n"},["scripts/items/decennial_dress_+1.lua"]={["Path"]="scripts/items/decennial_dress_+1.lua",["SHA256"]="467041edb479248b797d90776ca43807a8ce0d94356a5ed09c484bc2fe9eafe4",["Text"]="-----------------------------------\n-- ID: 10254\n-- Decennial Dress +1\n-- Dispense: Bowl of Moogurt\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.BOWL_OF_MOOGURT, 1 } })\nend\n\nreturn itemObject\n"},["scripts/items/decennial_ring.lua"]={["Path"]="scripts/items/decennial_ring.lua",["SHA256"]="f80e7f0a9ec17ac242a8aa0dbc2b1ee4bd8f5e1e424b6be7a345e08e3abd5f9d",["Text"]="-----------------------------------\n-- ID: 10796\n-- Item: Decennial Ring\n-- Experience point bonus\n-----------------------------------\n-- Bonus: +100%\n-- Duration: 720 min\n-- Max bonus: 10000 exp\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if target:hasStatusEffect(xi.effect.DEDICATION) then\n        result = xi.msg.basic.ITEM_UNABLE_TO_USE_2\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target)\n    local effect    = xi.effect.DEDICATION\n    local power     = 100\n    local duration  = 43200\n    local subpower  = 10000\n\n    xi.itemUtils.addItemExpEffect(target, effect, power, duration, subpower)\nend\n\nreturn itemObject\n"},["scripts/items/decorative_chair_set.lua"]={["Path"]="scripts/items/decorative_chair_set.lua",["SHA256"]="bbb6c7bc34eaf1774768c0e32d3e56089bd0c8dcd3fe1c58fddf6864f9e394af",["Text"]="-----------------------------------\n-- ID: 6378\n-- Item: Decorative Chair\n-- Item Effect: Grant Decorative chair key item\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nlocal keyItemId = xi.keyItem.DECORATIVE_CHAIR\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasKeyItem(keyItemId) then\n        return xi.msg.basic.ALREADY_HAVE_KEY_ITEM, 0, keyItemId\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:addKeyItem(keyItemId)\n    target:messageBasic(xi.msg.basic.OBTAINED_KEY_ITEM, 6378, keyItemId)\nend\n\nreturn itemObject\n"},["scripts/items/deductive_brocade_obi.lua"]={["Path"]="scripts/items/deductive_brocade_obi.lua",["SHA256"]="85628abc1850a1729524be20c51cc5de98ce2c38364d54e0d88d67731e50b85c",["Text"]="-----------------------------------\n-- ID: 15861\n-- Item: deductive_brocade_obi\n-- Item Effect: MND+10\n-- Duration: 3 Minutes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.MND_BOOST, xi.effectSourceType.EQUIPPED_ITEM, xi.item.DEDUCTIVE_BROCADE_OBI) ~= nil then\n        target:delStatusEffect(xi.effect.MND_BOOST, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.DEDUCTIVE_BROCADE_OBI)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.DEDUCTIVE_BROCADE_OBI) then\n        target:addStatusEffect(xi.effect.MND_BOOST, { duration = 180, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.DEDUCTIVE_BROCADE_OBI })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.MND, 10)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/deep-fried_shrimp.lua"]={["Path"]="scripts/items/deep-fried_shrimp.lua",["SHA256"]="33068fbef16eccd4b33a5b7aa9c81db0e28291c1994b31cbfcd3371671014191",["Text"]="-----------------------------------\n-- ID: 6276\n-- Item: deep-fried_shrimp\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- VIT +3\n-- Fire resistance +20\n-- Accuracy +20% (cap 70)\n-- Ranged Accuracy +20% (cap 70)\n-- Subtle Blow +8\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.VIT, 3)\n    effect:addMod(xi.mod.FIRE_MEVA, 20)\n    effect:addMod(xi.mod.FOOD_ACCP, 20)\n    effect:addMod(xi.mod.FOOD_ACC_CAP, 70)\n    effect:addMod(xi.mod.FOOD_RACCP, 20)\n    effect:addMod(xi.mod.FOOD_RACC_CAP, 70)\n    effect:addMod(xi.mod.SUBTLE_BLOW, 8)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/deep-fried_shrimp_+1.lua"]={["Path"]="scripts/items/deep-fried_shrimp_+1.lua",["SHA256"]="1c56cc61c12eabf2dfcf854ad4464aa7d197e3b49ba68597b23c7c1aa4e6ae4b",["Text"]="-----------------------------------\n-- ID: 6277\n-- Item: deep-fried_shrimp\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- VIT +4\n-- Fire resistance +21\n-- Accuracy +21% (cap 75)\n-- Ranged Accuracy +21% (cap 75)\n-- Subtle Blow +9\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.VIT, 4)\n    effect:addMod(xi.mod.FIRE_MEVA, 21)\n    effect:addMod(xi.mod.FOOD_ACCP, 21)\n    effect:addMod(xi.mod.FOOD_ACC_CAP, 75)\n    effect:addMod(xi.mod.FOOD_RACCP, 21)\n    effect:addMod(xi.mod.FOOD_RACC_CAP, 75)\n    effect:addMod(xi.mod.SUBTLE_BLOW, 9)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/demon_quiver.lua"]={["Path"]="scripts/items/demon_quiver.lua",["SHA256"]="0b8f01ddeac74a6b60cc22a44c13515c0b8cb5899d9f6f1d799a0106a6581132",["Text"]="-----------------------------------\n-- ID: 4224\n-- Demon Quiver\n-- When used, you will obtain one stack of Demon Arrows\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.DEMON_ARROW, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/demonic_sword.lua"]={["Path"]="scripts/items/demonic_sword.lua",["SHA256"]="8e29bf0dacb9638b2706e529694dbab5a3b79534423851fee23ef059f462391a",["Text"]="-----------------------------------\n-- ID: 16936\n-- Item: Demonic Sword\n-- Additional effect: darkness damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat  = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    local pTable =\n    {\n        chance         = 4 + utils.clamp(dStat * 4 / 54, 0, 4), -- linear interpolation\n        basePower      = math.randomInt(6, 8),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.DARK,\n        canMAB         = false,\n        canResist      = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/demonslicer.lua"]={["Path"]="scripts/items/demonslicer.lua",["SHA256"]="66aaec3a954ba69c38b6e211cd7e6d2d890ff8ffcac527a917c6cdda1be303e2",["Text"]="-----------------------------------\n-- ID: 16787\n-- Item: Demonslicer\n-- Additional effect: darkness damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat  = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    local pTable =\n    {\n        chance         = 4 + utils.clamp(dStat * 8 / 54, 0, 8), -- linear interpolation\n        basePower      = math.randomInt(9, 12),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.DARK,\n        canMAB         = false,\n        canResist      = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/denizanasi.lua"]={["Path"]="scripts/items/denizanasi.lua",["SHA256"]="74eb9a73e458ee534c64db65d42c6d4efc19575f17d92e74431eb3d5e36bb2d8",["Text"]="-----------------------------------\n-- ID: 5447\n-- Item: Denizanasi\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 1\n-- Mind -3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 1)\n    effect:addMod(xi.mod.MND, -3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/derfland_pear.lua"]={["Path"]="scripts/items/derfland_pear.lua",["SHA256"]="67747e866b5043e60b7c4af01f396294cd69f72f37de65397a76ce2a0c700330",["Text"]="-----------------------------------\n-- ID: 4352\n-- Item: derfland_pear\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Agility -3\n-- Intelligence 1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, -3)\n    effect:addMod(xi.mod.INT, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/detonator_belt.lua"]={["Path"]="scripts/items/detonator_belt.lua",["SHA256"]="0858bc929091b884861b9522e1b89dbf1439dd59f8ff7a82bf4ad6f003311ab0",["Text"]="-----------------------------------\n-- ID: 15921\n-- Detonator Belt\n-- Enchantment: 60Min, Costume - Cluster (Black)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if not target:canUseMisc(xi.zoneMisc.COSTUME) then\n        return xi.msg.basic.CANT_BE_USED_IN_AREA\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.COSTUME, { power = 290, duration = 3600, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/dexterity_potion.lua"]={["Path"]="scripts/items/dexterity_potion.lua",["SHA256"]="d7db0ed6110f89ad488656205076c36f880517bd26617ea9d66875c12511ee15",["Text"]="-----------------------------------\n--  ID: 4201\n--  Item: Dexterity Potion\n--  Dexterity 7\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.MEDICINE) then\n        return xi.msg.basic.ITEM_NO_USE_MEDICATED\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.DEX_BOOST, { power = 7, duration = 180, origin = user })\n    target:addStatusEffect(xi.effect.MEDICINE, { duration = 900, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/dhalmel_pie.lua"]={["Path"]="scripts/items/dhalmel_pie.lua",["SHA256"]="7753cfd7cf3362cb388844906a7e796eaeee455a020c01901aa75748c2a25909",["Text"]="-----------------------------------\n-- ID: 4411\n-- Item: dhalmel_pie\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Health 25\n-- Strength 4\n-- Agility 2\n-- Vitality 1\n-- Intelligence -2\n-- Mind 1\n-- Attack % 25\n-- Attack Cap 45\n-- Ranged ATT % 25\n-- Ranged ATT Cap 45\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 25)\n    effect:addMod(xi.mod.STR, 4)\n    effect:addMod(xi.mod.AGI, 2)\n    effect:addMod(xi.mod.VIT, 1)\n    effect:addMod(xi.mod.INT, -2)\n    effect:addMod(xi.mod.MND, 1)\n    effect:addMod(xi.mod.FOOD_ATTP, 25)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 45)\n    effect:addMod(xi.mod.FOOD_RATTP, 25)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 45)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/dhalmel_pie_+1.lua"]={["Path"]="scripts/items/dhalmel_pie_+1.lua",["SHA256"]="14b8bfd5515be93d98bd36706c99023b3590bb1831a8edc594eed53c493ce897",["Text"]="-----------------------------------\n-- ID: 4322\n-- Item: dhalmel_pie_+1\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- Health 25\n-- Strength 4\n-- Agility 2\n-- Vitality 1\n-- Intelligence -2\n-- Mind 1\n-- Attack % 25\n-- Attack Cap 50\n-- Ranged ATT % 25\n-- Ranged ATT Cap 50\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 25)\n    effect:addMod(xi.mod.STR, 4)\n    effect:addMod(xi.mod.AGI, 2)\n    effect:addMod(xi.mod.VIT, 1)\n    effect:addMod(xi.mod.INT, -2)\n    effect:addMod(xi.mod.MND, 1)\n    effect:addMod(xi.mod.FOOD_ATTP, 25)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 50)\n    effect:addMod(xi.mod.FOOD_RATTP, 25)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 50)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/dhalmel_steak.lua"]={["Path"]="scripts/items/dhalmel_steak.lua",["SHA256"]="7d9437587d132e4043a93ac2f1c66a588cff9fd0ba86fe7f57ee358dcb50d0d9",["Text"]="-----------------------------------\n-- ID: 4438\n-- Item: dhalmel_steak\n-- Food Effect: 180Min, All Races\n-----------------------------------\n-- Strength 4\n-- Intelligence -2\n-- Attack % 25\n-- Attack Cap 45\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, 4)\n    effect:addMod(xi.mod.INT, -2)\n    effect:addMod(xi.mod.FOOD_ATTP, 25)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 45)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/dhalmel_whistle.lua"]={["Path"]="scripts/items/dhalmel_whistle.lua",["SHA256"]="d1f2cd08dbe699ee9d6f5d10795946c9007f71d98fb82aec1b27ad1d726dd92c",["Text"]="-----------------------------------\n-- ID: 15505\n-- Item: dhalmel_whistle\n-- Item Effect: AGI +6\n-- Duration: 3 minutes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.DHALMEL_WHISTLE) ~= nil then\n        target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.DHALMEL_WHISTLE)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.DHALMEL_WHISTLE) then\n        target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 180, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.DHALMEL_WHISTLE })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, 6)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/dil.lua"]={["Path"]="scripts/items/dil.lua",["SHA256"]="b3f50154760fc685a57e43e959cf71daef7a9a097a3360d1ca9a6cc3a2567570",["Text"]="-----------------------------------\n-- ID: 5457\n-- Item: Dil\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 4\n-- Mind -6\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 4)\n    effect:addMod(xi.mod.MND, -6)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/dish_of_homemade_carbonara.lua"]={["Path"]="scripts/items/dish_of_homemade_carbonara.lua",["SHA256"]="9f8ed6f9142c995568280e47a241725fe4f574e1502ba86cd305f7b0a536c609",["Text"]="-----------------------------------\n-- ID: 5706\n-- Item: dish_of_homemade_carbonara\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- CHR +1\n-- Accuracy +12% (cap 80)\n-- Attack +10% (cap 40)\n-- Ranged Accuracy +12% (cap 80)\n-- Ranged Attack +10% (cap 40)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.CHR, 1)\n    effect:addMod(xi.mod.FOOD_ACCP, 12)\n    effect:addMod(xi.mod.FOOD_ACC_CAP, 80)\n    effect:addMod(xi.mod.FOOD_ATTP, 10)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 40)\n    effect:addMod(xi.mod.FOOD_RACCP, 12)\n    effect:addMod(xi.mod.FOOD_RACC_CAP, 80)\n    effect:addMod(xi.mod.FOOD_RATTP, 10)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 40)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/dish_of_hydra_kofte.lua"]={["Path"]="scripts/items/dish_of_hydra_kofte.lua",["SHA256"]="51407ec70c